#include <cstdio>
#include <vector>
#include <queue>

int main() {
    int n;
    scanf("%d", &n);
    std::priority_queue<long long> pq;
    for (int i = 0; i < n; ++i) {
        long long x; scanf("%lld", &x);
        pq.push(x);
    }

    while (pq.size() >= 2) {
        long long x = pq.top(); pq.pop();
        long long y = pq.top(); pq.pop();
        if (x != y) pq.push(x - y);
    }

    printf("%lld\n", pq.empty() ? 0LL : pq.top());
    return 0;
}
